// === Tab: Tiles ===
function genTiles(s = 10) {
	/*
	background(0)
	for (let x = S; x < width; x += S) line(x, 0, x, height)
	for (let y = S; y < height; y += S) line(0, y, width, y)
	*/
  stroke("cyan");
	strokeWeight(1);
	line(s * 0.5, s * 1.5, s * 1, s * 1.5);

	line(s * 1, s * 1.5, s * 2, s * 0.5)
	line(s * 2, s * 0.5, s * 3, s * 0.5)
	line(s * 3, s * 0.5, s * 4, s * 1.5)

	line(s * 1, s * 1.5, s * 2, s * 2.5)
	line(s * 2, s * 2.5, s * 3, s * 2.5)
	line(s * 3, s * 2.5, s * 4, s * 1.5)

	line(s * 4, s * 1.5, s * 4.5, s * 1.5)

	// |
	line(s * 0.5, s * 0.5, s * 0.5, s * 1);
	line(s * 0.5, s * 2, s * 0.5, s * 2.5);
	line(s * 2.5, s * 1, s * 2.5, s * 2);

	tiles = []
	const sz = s-1;
	// horizontal       size, image, arr pts[] (trbl/nesw)
	tiles.push(new Tile(s, get(0, s, sz, sz), [0,1,0,0]));
	tiles.push(new Tile(s, get(2*s, 0, sz, sz), [0,1,0,1]));
	tiles.push(new Tile(s, get(4*s, s, sz, sz), [0,0,0,1]));

	// vertical
	tiles.push(new Tile(s, get(0, 0, sz, sz), [0,0,1,0]));
	tiles.push(new Tile(s, get(2*s, s, sz, sz), [1,0,1,0]));
	tiles.push(new Tile(s, get(0, 2*s, sz, sz), [1,0,0,0]));

	// empty
	// tiles.push(new Tile(s, get(4*s, 0, sz, sz), [0,0,0,0]));

	// diagonal
	tiles.push(new Tile(s, get(s, 0, sz, sz), [0,1,1,0]));
	tiles.push(new Tile(s, get(3*s, 0, sz, sz), [0,0,1,1]));
	tiles.push(new Tile(s, get(s, 2*s, sz, sz), [1,1,0,0]));
	tiles.push(new Tile(s, get(3*s, 2*s, sz, sz), [1,0,0,1]));

	// console.log(tiles);
	return tiles;
}

class Tile {
	constructor(s, img, pts) {
		this.s = s;
		this.img = img;
		this.pts = pts;
	}

	draw(r = 0) {
		if (true || this.img) {
			// if (r) rotate(r);
			image(this.img, 0, 0, this.s-1, this.s-1);
		}
	}
}

// === Tab: WFC ===
class WFC {
	constructor(x, y, w, h, s, tiles) {
		this.pos = {x, y};
		this.sze = {w, h};
		this.dim = {x: ~~(w/s), y: ~~(h/s)}
		this.s = s; // cell size
		this.tiles = [...tiles];
		this.grid = [];
		for (let i = 0; i < this.dim.y; i++) {
			this.grid[i] = []
			for (let j = 0; j < this.dim.x; j++) {
				// console.log(`grid[${i},${j}]`);
				x = j * s;
				y = i * s;
				this.grid[i][j] = {
					i, j, x, y, s,
					tile: 0,
					entropy: [...tiles]
				}
			}
		}
	}

	getNumFreeCells() {
		let numFreeCells = 0;
		for (let row of this.grid) {
			for (let cell of row) {
				if (!cell.tile) numFreeCells++;
			}
		}
		return numFreeCells;
	}

	getLowestEntropy() {
		let lowestEntropyArr = [];
		for (let row of this.grid) {
			for (let cell of row) {
				if (!cell.tile) lowestEntropyArr.push(cell);
			}
		}
		lowestEntropyArr = lowestEntropyArr.sort((a, b) => a.entropy.length - b.entropy.length);
		if (lowestEntropyArr && lowestEntropyArr.length) {
			const lowestNumEntropy = lowestEntropyArr[0].entropy.length;
			lowestEntropyArr = lowestEntropyArr.filter((c) => c.entropy.length === lowestNumEntropy);
			return random(lowestEntropyArr);
		}
		return null;
	}

	collapse() {
		// if (this.getNumFreeCells === 0) return;
		let cell = this.getLowestEntropy()
		if (cell === null) {
			// console.log("no free cells");
			return;
		}
		if (cell.entropy.length) {
			// console.log("entropy.length " + cell.entropy.length)
			cell.tile = random(cell.entropy);
			// console.log(`pts: ${cell.tile.pts}`)
			cell.entropy = [];
			let i = cell.i, j = cell.j;
			// reduce neighboars
			if (i-1 >= 0) this.reduce(i-1, j, 2, cell.tile.pts[0])
			if (i+1 < this.dim.y) this.reduce(i+1, j, 0, cell.tile.pts[2])
			if (j-1 >= 0) this.reduce(i, j-1, 1, cell.tile.pts[3])
			if (j+1 < this.dim.x) this.reduce(i, j+1, 3, cell.tile.pts[1])
			return cell;
		} else {
			console.log("no fitting cell found", cell)
		}
	}

	reduce(i, j, idx, val) {
		var cell = this.grid[i][j];
		// console.log(`reduce(${i}, ${j}, ${idx}, ${val}, e.${cell.entropy.length})`);
		for (let ei = cell.entropy.length-1; ei >= 0; ei--) {
			const tile = cell.entropy[ei];
			if (tile.pts[idx] != val) cell.entropy.splice(ei, 1);
		}
		// console.log(`reduce(${i}, ${j}, ${idx}, ${val}, e.${cell.entropy.length})`);
	}

	draw() {
		push();
		// translate(this.pos.x, this.pos.y);
		for (let row of this.grid) {
			for (let cell of row) {
				push();
				translate(cell.x, cell.y)
				if (cell.tile) {
					cell.tile.draw();
					// text("" + cell.tile.pts, 0, 10);
				} else {
					let y = 10;
					for (let e of cell.entropy) {
						// text("" + e.pts, 0, y);
						y += 10;
					}
				}
				pop();
			}
		}
		pop();
	} // draw

}

